+// Pure builder for the SessionStart KBD context (bounded to 2 KB).
+export const MAX_CONTEXT_BYTES = 2048;
+const REMINDER_LINES = 8;
+export function buildSessionContext(waypointJson, reminder) {
+    let phase;
+    let next;
+    let status;
+    if (waypointJson !== undefined) {
+        try {
+            const wp = JSON.parse(waypointJson);
+            phase = typeof wp["phase"] === "string" ? wp["phase"] : undefined;
+            next = typeof wp["nextChange"] === "string" ? wp["nextChange"] : undefined;
+            status = typeof wp["status"] === "string" ? wp["status"] : undefined;
+        }
+        catch {
+            // A malformed waypoint yields no phase line; the reminder may still help.
+        }
+    }
+    if (phase === undefined && reminder === undefined)
+        return undefined;
+    const lines = ["KBD position (from .kbd-orchestrator, generated by the KBD runtime):"];
+    if (phase !== undefined)
+        lines.push(`- Active phase: ${phase}${status !== undefined ? ` (status: ${status})` : ""}`);
+    if (next !== undefined)
+        lines.push(`- Next change (derived from task state): ${next}`);
+    lines.push("- Select work from nextChange, never from exactNextCommand. Route work through /kbd-apply and the fhir-* personas (docs/agent-team.md).");
+    if (reminder !== undefined) {
+        lines.push("", "Position reminder (head):", ...reminder.split(/\r?\n/).slice(0, REMINDER_LINES));
+    }
+    let text = lines.join("\n");
+    while (Buffer.byteLength(text) > MAX_CONTEXT_BYTES)
+        text = text.slice(0, Math.floor(text.length * 0.9));
+    return text;
+}
